  "subscribe.checkingTrial": "మీ ఇమెయిల్‌కు ఉచిత ట్రయల్ అందుబాటులో ఉందో లేదో తనిఖీ చేయబడుతోంది…",
  "subscribe.trialEligible": "అర్హత ఉన్న కొత్త కస్టమర్‌లకు ఒక 7 రోజుల ఉచిత ట్రయల్ లభిస్తుంది. ఈ రోజు మీపై ఛార్జీ పడదు — మీరు ముందుగా రద్దు చేస్తే తప్ప, ట్రయల్ ముగిసినప్పుడు మీ మొదటి {price} చెల్లింపు చెల్లించాల్సి ఉంటుంది.",
  "subscribe.startTrial": "7 రోజుల ఉచిత ట్రయల్‌ను ప్రారంభించండి — {planName}",
  "subscribe.startingCheckout": "చెక్అవుట్ ప్రారంభించబడుతోంది…",
  "subscribe.noTrial": "ఈ ఇమెయిల్ ఇంతకు ముందు సబ్‌స్క్రైబ్ చేసింది, కాబట్టి కొత్త ట్రయల్ అందుబాటులో లేదు — ఈ రోజు మీపై {price} ఛార్జీ పడుతుంది.",
  "subscribe.subscribeButton": "{planName}కు సబ్‌స్క్రైబ్ చేయండి — నెలకు {price}",
  "subscribe.checkoutFailed": "చెక్అవుట్‌ను ప్రారంభించలేకపోయాము. ఏదీ ఛార్జ్ చేయబడలేదు.",
  "subscribe.stripeNote": "చెక్అవుట్‌ను Stripe సురక్షితంగా నిర్వహిస్తుంది. మీరు ఏదైనా ఛార్జీని ఆమోదించే ముందు ఖచ్చితమైన మొత్తాన్ని చూస్తారు.",
  "subscribe.noCardStored": "కార్డ్ వివరాలను Luminous StockHaven నిల్వ చేయదు. చెల్లింపులను Stripe ప్రాసెస్ చేస్తుంది.",
  "plans.backToWelcome": "స్వాగతానికి తిరిగి వెళ్లండి",
  "plans.eyebrow": "ప్లాన్‌లు & ఫీచర్‌లు",
  "plans.title": "StockHaven ప్లాన్‌లను పోల్చండి",
  "plans.intro": "మీరు ఏ ప్లాన్‌ను ఎంచుకున్నా ఒకే ఖాతా — Business ఐదు వ్యాపారాల వరకు వర్తిస్తుంది. ధరలు అమెరికన్ డాలర్లలో నెలవారీగా ఉంటాయి, అర్హత ఉన్న కొత్త వెబ్‌సైట్ కస్టమర్‌లు Essentials మరియు Business అంతటా ఒక ఏడు రోజుల ట్రయల్‌ను పొందవచ్చు. ఇప్పటికే ఉన్న Essentials సబ్‌స్క్రిప్షన్‌ను Businessకు అప్‌గ్రేడ్ చేయడం వల్ల ట్రయల్ మళ్లీ ప్రారంభం కాదు లేదా మరొక ఉచిత ట్రయల్ సృష్టించబడదు. వెబ్‌సైట్ ప్లాన్ ధరలు వర్తించే పన్నులకు ముందువి, ఏవైనా ఉంటే. మీరు సబ్‌స్క్రిప్షన్‌ను అధికారికం చేసే ముందు మీ ఖచ్చితమైన ఛార్జీ చూపబడుతుంది.",
  "plans.availableAtLaunch": "మొబైల్ ప్రారంభంలో అందుబాటులో ఉంటుంది",
  "plans.yourPlan": "మీ ప్లాన్",
