  "upgrade.pendingCheckoutIntro": "మీరు సబ్‌స్క్రిప్షన్‌ను ఎంచుకునే వరకు ఈ కొత్త వర్క్‌స్పేస్ Essentialsకు పరిమితం చేయబడింది. అర్హత ఉన్న కొత్త కస్టమర్‌లు ఖాతాకు ఒక {days} రోజుల ట్రయల్‌ను పొందవచ్చు.",
  "upgrade.intro": "అర్హత ఉన్న కొత్త కస్టమర్‌లు ఖాతాకు ఒక {days} రోజుల ట్రయల్‌ను పొందవచ్చు, ప్లాన్‌కు ఒక ట్రయల్ కాదు. Essentials నుండి Businessకు మారడం వల్ల మరొక ఉచిత ట్రయల్ ఎప్పుడూ ప్రారంభం కాదు. మీరు దీనిపై ఉన్నారు",
  "upgrade.introGrandfathered": " — పూర్తి Business వర్క్‌స్పేస్, ఎటువంటి ఛార్జీ లేకుండా.",
  "upgrade.introTrial": " (ట్రయల్).",
  "upgrade.introPeriod": ".",
  "upgrade.pastDueTitle": "చెల్లింపు గడువు దాటింది",
  "upgrade.pastDueBody": "మీ చివరి చెల్లింపు జరగలేదు, కాబట్టి ఈ సబ్‌స్క్రిప్షన్ గడువు దాటింది. క్రింద మీ చెల్లింపు పద్ధతిని నవీకరించండి — Stripe దాని స్వంత షెడ్యూల్‌లో మళ్లీ ప్రయత్నిస్తుంది, మీ సబ్‌స్క్రిప్షన్ ముందుగా రద్దు చేయబడదు. మీకు సహాయం కావాలంటే, ఇమెయిల్ చేయండి",
  "upgrade.updatePaymentMethod": "చెల్లింపు పద్ధతిని నవీకరించండి",
  "upgrade.startingPaymentUpdate": "చెల్లింపు నవీకరణ ప్రారంభించబడుతోంది…",
  "upgrade.paymentUpdateFailed": "చెల్లింపు నవీకరణను ప్రారంభించలేకపోయాము.",
  "upgrade.perMonth": "/ నెల",
  "upgrade.taxNote": "వర్తించే పన్నులతో పాటు, ఏవైనా ఉంటే. మీరు ఛార్జీని ఆమోదించే ముందు ప్రొవైడర్ మీ ఖచ్చితమైన మొత్తాన్ని తప్పనిసరిగా చూపాలి.",
  "upgrade.startSubscription": "సబ్‌స్క్రిప్షన్‌ను ప్రారంభించండి",
  "upgrade.trialCheckedNote": "అర్హత ఉన్న కొత్త కస్టమర్‌లకు ఒక 7 రోజుల ఉచిత ట్రయల్ లభిస్తుంది — చెక్అవుట్‌కు ముందు సర్వర్ ద్వారా తనిఖీ చేయబడుతుంది.",
  "upgrade.upgradeToBusiness": "Businessకు అప్‌గ్రేడ్ చేయండి",
  "upgrade.upgradeNote": "అదే సబ్‌స్క్రిప్షన్, రెండవ ట్రయల్ లేదు, తక్షణ ఛార్జీ లేదు — ధర వ్యత్యాసం మీ తదుపరి ఇన్‌వాయిస్‌లో వస్తుంది.",
  "upgrade.upgradeTrialNote": "మీ ట్రయల్ {date} వరకు కొనసాగుతుంది, ఆ తర్వాత Business నెలకు $29.99తో ప్రారంభమవుతుంది.",
  "upgrade.subscribeAgain": "మళ్లీ సబ్‌స్క్రైబ్ చేయండి",
  "upgrade.subscribeAgainNote": "ఇది కొత్త సబ్‌స్క్రిప్షన్‌ను ప్రారంభిస్తుంది — తిరిగి వచ్చే ఇమెయిల్‌కు రెండవ ఉచిత ట్రయల్ లభించదు.",
  "upgrade.downgradeToEssentials": "Essentialsకు డౌన్‌గ్రేడ్ చేయండి",
  "upgrade.downgradeNote": "Business మీ చెల్లించిన కాలం ముగిసే వరకు కొనసాగుతుంది, ఆ తర్వాత Essentials నెలకు $14.99తో ప్రారంభమవుతుంది. డౌన్‌గ్రేడ్ చేసినందుకు వాపసు లేదు.",
  "upgrade.contactSupport": "మీ ప్లాన్‌ను మార్చడానికి మద్దతును సంప్రదించండి",
  "upgrade.signInAsOwner": "వ్యాపార యజమానిగా సైన్ ఇన్ చేయండి",
  "upgrade.cancelSubscription": "సబ్‌స్క్రిప్షన్‌ను రద్దు చేయండి",
  "upgrade.cancelTrialNote": "మీ ట్రయల్ సమయంలో రద్దు చేయడం వల్ల మీ పూర్తి 7 రోజులు ఉంటాయి — ప్రాప్యత {date}న ముగుస్తుంది, మీపై ఛార్జీ పడదు.",
  "upgrade.cancelNote": "మీ చెల్లించిన కాలం చివరిలో రద్దు అవుతుంది — అప్పటి వరకు మీకు పూర్తి ప్రాప్యత ఉంటుంది.",
  "upgrade.canceledEndsOn": "ఈ సబ్‌స్క్రిప్షన్ రద్దు చేయబడింది మరియు {date}న ముగుస్తుంది. అప్పటి వరకు మీకు పూర్తి ప్రాప్యత ఉంటుంది.",
  "upgrade.downgradeWarning1": "3కి మించిన సిబ్బంది ప్రాప్యతను కోల్పోతారు — Essentialsలో 3 అదనపు సిబ్బంది చేర్చబడ్డారు.",
  "upgrade.downgradeWarning2": "అదనపు వ్యాపారాలు మరియు దుకాణాలు (2, 3, 4, 5 — మొదటిదానికి మించి ఎన్ని ఉన్నా) ఇకపై అందుబాటులో ఉండవు.",
  "upgrade.downgradeWarning3": "ఎగుమతి పోతుంది — CSV/Excel ఎగుమతి లేదు, దిగుమతి మాత్రమే.",
  "upgrade.downgradeWarning4": "ఇతర Business-మాత్రమే పేజీలతో పాటు బండిల్‌లు మరియు సరఫరాదారుల పేజీలు పోతాయి.",
  "upgrade.downgradeWarning5": "ఇన్వెంటరీ స్వయంగా Essentialsలోకి సజావుగా మారుతుంది — మీరు నిల్వ చేసినది ఏదీ తొలగించబడదు.",
  "upgrade.dialogUpgradeDesc": "మీ ట్రయల్ మరియు సబ్‌స్క్రిప్షన్ అదే సబ్‌స్క్రిప్షన్‌లో ఉంటాయి — రెండవ సబ్‌స్క్రిప్షన్ లేదు, కొత్త ట్రయల్ లేదు.",
  "upgrade.dialogDowngradeDesc": "డౌన్‌గ్రేడ్ చేయడం వల్ల మీ డేటా ఎప్పుడూ తొలగించబడదు — కానీ దానిలో కొంత భాగం ప్రాప్యత లేకుండా పోతుంది. ముందుగా దీన్ని చదవండి.",
