  "upgrade.doneDowngrade": "డౌన్‌గ్రేడ్ షెడ్యూల్ చేయబడింది.",
  "upgrade.doneTrial": "మీ ట్రయల్ {trialEnds} వరకు కొనసాగుతుంది, ఆ తర్వాత Business నెలకు $29.99తో ప్రారంభమవుతుంది. మీ మొదటి Business ఛార్జీ {firstCharge}న ఉంటుంది.",
  "upgrade.doneUpgradeNow": "Business ఇప్పుడు నెలకు $29.99తో ప్రారంభమవుతుంది. ధర వ్యత్యాసం మీ తదుపరి ఇన్‌వాయిస్‌లో వస్తుంది — తక్షణ ఛార్జీ లేదు.",
  "upgrade.doneDowngradeBody": "మీరు {date} వరకు Businessను ఉంచుకుంటారు, ఆ తర్వాత Essentials నెలకు $14.99తో ప్రారంభమవుతుంది. డౌన్‌గ్రేడ్ చేసినందుకు వాపసు లేదు.",
