  "upgrade.previewToValue": "{name} — నెలకు {price}",
  "upgrade.previewUpgradeNote": "అప్‌గ్రేడ్ చేయడం వల్ల మీ ఉచిత ట్రయల్ ఎప్పుడూ మళ్లీ ప్రారంభం కాదు, అది ఎప్పుడూ రెండవ సబ్‌స్క్రిప్షన్‌ను సృష్టించదు.",
