  "billing.readiness.inspect": "చెక్అవుట్ సంసిద్ధతను పరిశీలించండి (ఛార్జీ లేదు)",
  "billing.readiness.unknown": "చదవడానికి-మాత్రమే తనిఖీ సంసిద్ధతను నిర్ధారించలేకపోయింది ({state}). ఏదీ మారలేదు.",
  "billing.readiness.ready": "Stripe చెక్అవుట్ సిద్ధంగా ఉంది — కీలు, వెబ్‌హుక్ ధృవీకరణ మరియు ధృవీకరణ పత్రాలు అన్నీ నిర్ధారించబడ్డాయి.",
  "billing.readiness.complimentaryProtected": "మీ ఉచిత Business వర్క్‌స్పేస్ రక్షించబడింది. అది చెల్లించే Essentials పరీక్ష ఖాతాగా మారకూడదు.",
  "billing.readiness.environmentIncomplete": "Stripe చెక్అవుట్ ఆధారాలు, వెబ్‌హుక్ ధృవీకరణ లేదా యాప్ రిటర్న్ చిరునామా అన్నీ నిర్ధారించలేకపోయాము. చెక్అవుట్ ప్రారంభం కాకూడదు.",
  "billing.readiness.ownerHasHistory": "ఈ యజమాని వద్ద మునుపటి సబ్‌స్క్రిప్షన్ లేదా ట్రయల్ ఆధారాలు ఉన్నాయి. రెండవ చెక్అవుట్ సృష్టించకూడదు.",
  "billing.readiness.trialAlreadyUsed": "పరిచయ ట్రయల్ ఇప్పటికే ఉపయోగించబడింది లేదా రిజర్వ్ చేయబడింది. పునరావృత ట్రయల్ ప్రారంభం కాకూడదు.",
  "billing.readiness.trialEligibilityUnverified": "ఈ యజమాని కోసం ఒకసారి-మాత్రమే ట్రయల్ అర్హత ధృవీకరించబడలేదు. చెక్అవుట్ నిరోధించబడే ఉంటుంది.",
  "billing.readiness.testModeUnverified": "ఖాతా రికార్డులు చదవదగినవి, కానీ సురక్షితమైన Stripe పరీక్ష-మోడ్ నియంత్రణ మరియు చెల్లింపు-పునరుద్ధరణ నెరవేర్పు ధృవీకరించబడలేదు. చెక్అవుట్ నిరోధించబడే ఉంటుంది.",
  "billing.readiness.entitlementNotUnique": "ఇప్పటికే ఉన్న ప్లాన్ సమాచారం లేదు లేదా అస్పష్టంగా ఉంది. చెక్అవుట్ ప్రారంభం కాకూడదు.",
  "billing.readiness.accountBillingIncomplete": "ఖాతా బిల్లింగ్ చరిత్రను పూర్తిగా చదవలేకపోయాము. చెక్అవుట్ ప్రారంభం కాకూడదు.",
  "billing.readiness.billingHistoryIncomplete": "పూర్తి యజమాని చరిత్రను ధృవీకరించలేకపోయాము. చెక్అవుట్ ప్రారంభం కాకూడదు.",
  "billing.readiness.ownershipMismatch": "ఏదైనా సబ్‌స్క్రిప్షన్ ప్రారంభించడానికి ముందు ఖాతా యాజమాన్యం లేదా బిల్లింగ్ రికార్డులకు సమీక్ష అవసరం.",
  "billing.readiness.catalogUnverified": "ఆమోదించబడిన నెలకు $14.99 సర్వర్ చెక్అవుట్ నిర్వచనానికి ధృవీకరణ అవసరం.",
  "billing.readiness.auditUnavailable": "చదవడానికి-మాత్రమే సర్వర్ తనిఖీ అందుబాటులో లేదు. చెల్లింపు లేదా ఖాతా మార్పు ఏదీ జరగలేదు.",
  "billing.dryRun.ariaLabel": "పరీక్ష అప్‌గ్రేడ్ అనుకరణ",
  "billing.dryRun.title": "Essentials → Business — అభ్యాస అనుకరణ",
  "billing.dryRun.body": "ఈ బ్రౌజర్‌లో పూర్తిగా కల్పిత రికార్డులను ఉపయోగించి ప్రతిపాదిత అప్‌గ్రేడ్ నియమాలను అభ్యసించండి. ఇది మీ అసలు TEST — పైజామా ప్యాంట్స్ నమూనా, మీ ప్రస్తుత Business వర్క్‌స్పేస్, Stripe, ట్రయల్‌లు, సబ్‌స్క్రిప్షన్‌లు లేదా ఇన్వెంటరీని చదవదు లేదా మార్చదు.",
  "billing.dryRun.runButton": "స్థానిక అప్‌గ్రేడ్ అనుకరణను అమలు చేయండి (ఛార్జీ లేదు)",
  "billing.dryRun.passed": "కల్పిత దృశ్యం దాని స్థానిక తనిఖీలను దాటింది",
  "billing.dryRun.blocked": "కల్పిత దృశ్యం నిరోధించబడింది",
  "billing.dryRun.example": "ఉదాహరణ: Essentials (నెలకు $14.99) → Business (నెలకు $29.99), వర్తించే పన్నుకు ముందు.",
  "billing.dryRun.preserved": "అదే సబ్‌స్క్రిప్షన్ నిలుపబడింది, ఒక అసలు ట్రయల్ నిలుపబడింది, అనుకరించిన పైజామా ఇన్వెంటరీ మార్పు లేకుండా ఉంది. అసలు, ప్రొవైడర్-నిర్ధారించిన చెల్లింపు పునరుద్ధరణ ప్రాప్యతను మార్చడాన్ని సమర్థించే వరకు ఉదాహరణ కస్టమర్ Essentialsలోనే ఉంటారు.",
  "billing.dryRun.limitations": "స్థానిక అనుకరణ Stripe సబ్‌స్క్రిప్షన్ మార్పులను, చెల్లింపును, వెబ్‌హుక్‌ను, పన్ను-సహిత కోట్‌ను, ప్రత్యక్ష సబ్‌స్క్రిప్షన్‌ను లేదా మీ అసలు వ్యాపార రికార్డులను పరీక్షించదు.",
