  "reports.missingMoney": "ఈ వీక్షణలోని {units} యూనిట్లకు {label} నమోదు చేయబడలేదు. తప్పిపోయిన డబ్బు ఎప్పుడూ సున్నాగా పరిగణించబడదు — వాటిని ఉచితంగా లెక్కించకుండా సంఖ్యల నుండి వదిలివేయబడతాయి. ఆ ఉత్పత్తులపై సంఖ్యను జోడించండి మరియు మొత్తాలు నిండుతాయి.",
