  "settings.deletion.checkError": "ఇప్పటికే ఉన్న అభ్యర్థనలను ప్రస్తుతం తనిఖీ చేయలేకపోయాం. మీరు ఇంకా అభ్యర్థనను సమర్పించడానికి ప్రయత్నించవచ్చు.",
  "settings.deletion.confirmError": "మీ తొలగింపు అభ్యర్థనను మేము నిర్ధారించలేకపోయాం. దయచేసి మళ్ళీ ప్రయత్నించండి.",
