  "settings.pastDue.body": "మీ చివరి చెల్లింపు జరగలేదు. అప్‌గ్రేడ్ పేజీ నుండి మీ చెల్లింపు పద్ధతిని నవీకరించండి — Stripe దాని స్వంత షెడ్యూల్ ప్రకారం మళ్ళీ ప్రయత్నిస్తుంది, మరియు మీ సభ్యత్వం ముందుగా రద్దు చేయబడదు. ఏమి చేయాలో మీకు ఖచ్చితంగా తెలియకపోతే, theluminousbookshop@outlook.com వద్ద సపోర్ట్‌ను సంప్రదించండి.",
