  "settings.switcher.taglinePlaceholder": "ఐచ్ఛికం",
  "settings.switcher.upgrade": "అప్‌గ్రేడ్",
  "settings.title": "సెట్టింగ్‌లు",
  "settings.trial.cancelKeeps": "మీ ట్రయల్ సమయంలో రద్దు చేయడం మీ పూర్తి 7 రోజులను ఉంచుతుంది — యాక్సెస్ {date} న ముగుస్తుంది, మరియు మీకు ఛార్జ్ చేయబడదు.",
  "staff.access.noSeatBody": "ఈ వ్యాపారం కోసం మీ ఖాతాకు సిబ్బంది సీటు లేదు, కాబట్టి దాని స్టాక్ మూసివేయబడి ఉంటుంది. Staff & roles లో మిమ్మల్ని జోడించమని యజమానిని అడగండి.",
  "staff.access.noSeatTitle": "ఈ వ్యాపారం మీ లాగిన్‌కు తెరవబడలేదు",
  "staff.access.pendingBody": "ఈ వ్యాపారానికి మీ ఇమెయిల్ కోసం ఇంకా సక్రియం కాని ఆహ్వానం ఉంది. మీ సిబ్బంది స్థితిని క్రియాశీలంగా సెట్ చేయమని యజమానిని అడగండి. అప్పటి వరకు ఇక్కడ ఏదీ కనిపించదు.",
  "staff.access.pendingTitle": "మీ ఆహ్వానం ఇంకా క్రియాశీలంగా లేదు",
  "staff.access.signOut": "సైన్ అవుట్",
  "staff.access.suspendedBody": "నిర్వాహకుడు క్రియాశీల వ్యాపారం కోసం ఈ సిబ్బంది ఖాతాను నిలిపివేశారు. మిమ్మల్ని మళ్ళీ క్రియాశీలంగా సెట్ చేయమని వారిని అడగండి, తర్వాత మళ్ళీ సైన్ ఇన్ చేయండి.",
  "staff.access.suspendedTitle": "మీ యాక్సెస్ విరామంలో ఉంది",
  "staff.addFirst": "మొదటి సిబ్బంది సభ్యుడిని జోడించండి",
  "staff.addMember": "సిబ్బంది సభ్యుడిని జోడించండి",
  "staff.emptyBody": "ఒక వ్యక్తిని జోడించండి, వారికి ఒక పాత్రను మరియు దానితో వచ్చే అనుమతులను ఇవ్వండి, మరియు వారు ఈ వ్యాపారంలోకి సైన్ ఇన్ చేయడానికి ఇమెయిల్ ద్వారా ఆహ్వానించబడతారు.",
  "staff.emptyTitle": "ఇంకా సిబ్బంది లేరు",
  "staff.eyebrow": "బృందం",
  "staff.how.p1": "ప్రతి సభ్యుడికి ఒక పాత్ర మరియు వారి స్వంత అనుమతుల జాబితా ఉంటుంది, కాబట్టి మీరు ఒక పాత్ర నుండి ప్రారంభించి కొత్త పాత్రను తయారు చేయకుండా ఒక విషయాన్ని మార్చవచ్చు. పాత్రను సవరించడం దానిపై ఇప్పటికే ఉన్న సభ్యులను తిరిగి రాయదు — వారి పాత్ర డిఫాల్ట్‌లను మళ్ళీ వర్తింపజేయడానికి సభ్యుడిని తెరవండి.",
  "staff.how.p2": "కస్టమ్ పాత్రలు Business ఫీచర్: Essentials ఐదు అంతర్నిర్మిత పాత్రలను (Owner, Manager, Stock clerk, Sales clerk, Viewer) ఉపయోగిస్తుంది.",
  "staff.how.p3": "ఆహ్వానాలు ఇమెయిల్ ద్వారా పంపబడతాయి. సభ్యుడు వారు అంగీకరించిన తర్వాత మాత్రమే సైన్ ఇన్ చేయగలరు, మరియు ఈ జాబితా నుండి ఎవరినైనా తీసివేయడం వారి యాప్ ఖాతాను తొలగించదు.",
  "staff.how.p4": "స్టోర్ అనేది ఒక వ్యక్తికి కేటాయించబడిన స్థానం. ఇది వారి కార్డుపై నమోదు చేయబడుతుంది; వారు ఏమి తెరవగలరు అనేది ఇంకా వారి పాత్ర మరియు అనుమతుల ద్వారానే నిర్ణయించబడుతుంది.",
  "staff.how.p5": "ప్రతి వ్యక్తి ఏమి తెరవగలరో అనుమతులు నిర్ణయిస్తాయి: వారి పాత్రకు వెలుపల ఉన్న మెను అంశాలు దాచబడతాయి, మరియు నిరోధించబడిన చిరునామా పేజీకి బదులుగా “మీ పాత్రపై లేదు” నోటీసును చూపుతుంది. ఆ వ్యక్తి తదుపరిసారి యాప్‌ను లోడ్ చేసినప్పుడు మార్పు వర్తిస్తుంది; సభ్యుడిని నిలిపివేయడం వారిని పూర్తిగా లాక్ చేస్తుంది.",
  "staff.how.p6": "నిర్వాహకులు అన్ని డేటాను చూడవచ్చు మరియు మార్చవచ్చు, యాప్ వినియోగదారులు మరియు పాత్రలను నిర్వహించవచ్చు, మరియు సిబ్బంది పాత్ర ద్వారా ఎప్పుడూ పరిమితం చేయబడరు. సిబ్బంది రికార్డు లేని వ్యక్తి — కొత్త వ్యాపారం యజమాని — పూర్తి యాక్సెస్‌ను నిలుపుకుంటారు.",
  "staff.howTitle": "సిబ్బంది మరియు పాత్రలు ఎలా పని చేస్తాయి",
