  "printLib.bluetoothUnavailable": "Bluetooth ముద్రణకు డెస్క్‌టాప్ Chrome లేదా Edge, లేదా Android Chrome అవసరం. ఇది iOS Safariలో పనిచేయదు — iPhoneలో, AirPrintతో Wi-Fi ద్వారా ముద్రించండి, లేదా మొబైల్ యాప్ నుండి Bluetoothను ఉపయోగించండి (మొబైల్ యాప్‌తో వస్తుంది).",
  "printLib.usbUnavailable": "వెబ్‌సైట్ నుండి USB ముద్రణకు Android Chrome మరియు USB OTG కేబుల్ అవసరం. డెస్క్‌టాప్‌లో, ప్రింటర్‌ను కంప్యూటర్‌కు కనెక్ట్ చేసి ముద్రించు బటన్‌ను ఉపయోగించండి — అది అక్కడ ఇన్‌స్టాల్ చేసిన ప్రింటర్ ద్వారా ముద్రిస్తుంది. iPhoneలు USB ద్వారా నేరుగా ముద్రించలేవు — AirPrintతో Wi-Fiను ఉపయోగించండి, లేదా మొబైల్ యాప్ నుండి Bluetoothను ఉపయోగించండి (మొబైల్ యాప్‌తో వస్తుంది).",
